// Bundled onboarding screenshots generated by `npm run onboarding:capture` -> `docs/onboarding/*.png`.
const imageModules = import.meta.glob<string>('../../docs/onboarding/*.png', {
  import: 'default',
  eager: true,
})

const byName = new Map<string, string>(
  Object.entries(imageModules).map(([filePath, url]) => [filePath.split('/').pop() ?? filePath, url]),
)

export function onboardingImageUrl(filename: string): string | null {
  return byName.get(filename) ?? null
}
